import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { BackButton } from './BackButton';

interface Post {
  id: number;
  title: string;
  body: string;
  userId: number;
}

interface Comment {
  id: number;
  postId: number;
  name: string;
  email: string;
  body: string;
}

interface PageProps {
  params: Promise<{
    id: string;
  }>;
}

export const revalidate = 300; // 5 minutes

export async function generateStaticParams() {
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts').then(
    (res) => res.json()
  );

  return posts.slice(0, 10).map((post: Post) => ({
    id: post.id.toString(),
  }));
}

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] }> {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`).then((res) => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`).then((res) =>
        res.json()
      ),
    ]);

    if (!post.id) {
      notFound();
    }

    return { post, comments };
  } catch (error) {
    notFound();
  }
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params;
  const { post } = await getPostData(id);

  return {
    title: post.title,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  };
}

export default async function BlogPost({ params }: PageProps) {
  const { id } = await params;
  const { post, comments } = await getPostData(id);

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

